  } });
  const sourceIds = { type: 'array', maxItems: 32, items: string('Previously saved source ID', 96) };
  const point = object({ x: { anyOf: [{ type: 'number' }, { type: 'string', maxLength: 80 }] }, y: { type: 'number' } }, ['x', 'y']);
