*10|export const REVIEW_TOOLS = ['web_search', 'fetch_source', 'read_pdf', 'read_attachment', 'read_note', 'search_notes', 'recall_conversation'];
*11|export const REVIEW_LIMITS = Object.freeze({ requests: 4, tools: 6, outputTokens: 16000, requestTokens: 8000, timeoutMs: 180000, packetChars: 64000, images: 4, imageBytes: 12 * 1024 * 1024 });
