*13|export function shouldReview(entries, draft) {
*14|  const length = textOf(draft?.message?.content).trim().length;
*15|  return length >= 1800 || (length >= 500 && entries.some(entry => entry.message?.role === 'toolResult'
*16|    && ['fetch_source', 'read_pdf', 'read_note', 'read_attachment'].includes(entry.message.toolName)));
