*85|export function boundRequests(session, stats, limits, stopped, estimateTokens) {
*86|  const original = session.agent.streamFunction;
*87|  session.agent.streamFunction = (model, context, options) => {
*88|    if (stopped() || stats.requests >= limits.requests || stats.outputTokens >= limits.outputTokens) return stoppedStream(model, 'Review budget exhausted or stopped');
*89|    const modelLimit = Number.isFinite(model.maxTokens) && model.maxTokens > 0 ? model.maxTokens : limits.requestTokens;
*90|    const maxTokens = Math.min(modelLimit, limits.requestTokens, limits.outputTokens - stats.outputTokens);
*91|    if (estimateTokens && model.contextWindow > 0) {
*92|      // Provider-neutral estimate, not a tokenizer: include tools/system text,
*93|      // image estimates and headroom. Never silently drop ongoing tool results.
*94|      const input = Math.ceil((String(context.systemPrompt || '').length + JSON.stringify(context.tools || []).length) / 3)
*95|        + (context.messages || []).reduce((sum, message) => sum + Math.ceil(estimateTokens(message) * 1.3) + 32, 0);
*96|      stats.estimatedInputTokens = input;
*97|      if (input + maxTokens > Math.floor(model.contextWindow * .9)) return stoppedStream(model, 'Review context budget exhausted; unexamined claims remain unverified');
*98|    }
*99|    stats.requests++;
*100|    return original(model, context, { ...options, maxTokens });
*101|  };
*102|  return () => { session.agent.streamFunction = original; };
