*106|export function reviewLimitsForModel(model, limits = REVIEW_LIMITS) {
*107|  if (!Number.isFinite(model.contextWindow) || model.contextWindow <= 0) return limits;
*108|  return { ...limits, packetChars: Math.min(limits.packetChars, Math.floor(model.contextWindow * .75)),
*109|    requestTokens: Math.min(limits.requestTokens, Math.max(1, Math.floor(model.contextWindow / 8))),
*110|    images: Math.min(limits.images, Math.floor(model.contextWindow / 16000)) };
