*126|    noExtensions: true, noSkills: true, noPromptTemplates: true, noThemes: true, noContextFiles: true,
*127|    systemPrompt: REVIEW_PROMPT, appendSystemPrompt: [], agentsFilesOverride: () => ({ agentsFiles: [] }), appendSystemPromptOverride: () => [] });
*128|  await loader.reload();
*129|  let session, timer, timeout = false, report, error;
*130|  const abort = () => session?.agent.abort();
*131|  try {
*132|    if (signal?.aborted) throw signal.reason || new Error('Review stopped');
*133|    const tools = createResearchTools(vault, { getConversationId: () => conversation.id, getConversationEntries: () => history, canReadImages: () => model.input?.includes('image') === true })
